/**
 * A stand-in for Forma, for building themes in a plain browser.
 *
 * It answers from `library.json`: the real engine's output for the repository's fixture
 * library, regenerated by `cargo run -p forma-core --example mock_snapshot`. What a theme sees
 * here is what Forma would send. Favourites, settings and play stats change in memory;
 * views are a snapshot, so a new favourite does not move into the Favourites view.
 */
import type { Backend } from '../backend.js';
import { type ErrorCode, FormaError } from '../errors.js';
import type {
  AddonInfo,
  AddonPage,
  AddonRow,
  NameStyle,
  User,
  CatalogueAddon,
  BluetoothDevice,
  MediaKind,
  ScraperOffers,
  ScraperSettings,
  ScraperSource,
  ScraperStatus,
  Browse,
  Collection,
  RaSession,
  RoomFilter,
  BatoceraSetting,
  OptionItem,
  OptionsPage,
  OptionsScope,
  InfoItem,
  SystemSetting,
  StorePackage,
  DefaultView,
  EthernetConfig,
  Game,
  GameEnd,
  BiosMissing,
  GameStart,
  LaunchRequest,
  SystemBios,
  LibraryChanged,
  MusicSource,
  MusicStatus,
  NetplayRoom,
  NetworkStatus,
  Radio,
  RaGame,
  RaUser,
  SystemSummary,
  ThemeInfo,
  CatalogueTheme,
  Fetched,
  Magazine,
  ThemeCatalogue,
  Unsubscribe,
  ViewInfo,
  WifiNetwork,
  ShaderPage
} from '../types.js';
import data from './library.json' with { type: 'json' };

export interface MockOptions {
  /** How long a mock game "plays" before `game:end`. */
  playMs?: number;
  /** Permissions the mock pretends the theme declared, e.g. `settings.system`. */
  permissions?: string[];
  /** Pretend RetroAchievements is set up (default) or not. */
  ra?: boolean;
  /** Systems whose BIOS the mock pretends is missing: their games ask before starting. */
  biosMissing?: string[];
}

interface Snapshot {
  apiVersion: string;
  systems: SystemSummary[];
  views: ViewInfo[];
  games: Game[];
  browse: Record<string, Browse>;
  ra: { user: RaUser; games: Record<string, RaGame> };
  lobby: NetplayRoom[];
  network: { status: NetworkStatus; wifi: WifiNetwork[] };
  batocera: BatoceraSetting[];
  music: { sources: MusicSource[]; radios: Radio[] };
  /** The engine's option pages: `global`, and `system|emulator|core` (empty: not set). */
  options: Record<string, OptionsPage>;
  system: { info: InfoItem[]; settings: SystemSetting[] };
  store: StorePackage[];
}

const snapshot = data as unknown as Snapshot;
/** How many pages each mock magazine has. */
const MAGAZINE_PAGES = 8;

type Handler = (payload: unknown) => void;

/** A system's BIOS in the mock: its one file, not there. */
function mockBios(system: string): SystemBios {
  const fullname = snapshot.systems.find((s) => s.name === system)?.fullname ?? system;
  return {
    system,
    fullname,
    needed: true,
    missing: true,
    files: [
      { file: `bios/${system}_bios.bin`, md5: '0123456789abcdef0123456789abcdef', state: 'missing' }
    ]
  };
}

function fail(code: ErrorCode, message: string): never {
  throw new FormaError(code, message);
}

/** Lower-case without accents, for search the way SQLite's FTS does it. */
function fold(s: string): string {
  return s
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase();
}

